#!/bin/bash
# Download everything this environment needs (run on a node with internet).
#
# Idempotent: files already present with the right checksum are skipped.
#
# Estimated total download size: < 0.3 MB (nine ISCAS85 .bench netlists)
# Estimated disk usage after extraction: < 0.3 MB
#
# The ISCAS85 combinational benchmark circuits (Brglez & Fujiwara, 1985) are
# fetched from the public mirror at Tallinn University of Technology.  They
# are the golden netlists from which the train split (data/iscas85_train) and
# the hidden test split were generated by injecting gate-type faults (c432 and
# c499 are not used by the current splits but are kept for development).  The
# train split itself is tracked in git (data/iscas85_train/*.gz); the netlists
# are needed by the audit's netlist-matching check, to regenerate the split
# (python data/circuit_benchmark.py) or to build new instances.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"

DEST="data/downloads/iscas85"
BASE_URL="https://pld.ttu.ee/~maksim/benchmarks/iscas85/bench"
mkdir -p "$DEST"

# name  sha256-prefix
while read -r name sha; do
  file="$DEST/$name.bench"
  if [ -f "$file" ] && [ "$(sha256sum "$file" | cut -c1-16)" = "$sha" ]; then
    echo "ok   $file"
    continue
  fi
  echo "get  $BASE_URL/$name.bench"
  curl -fsSL --retry 3 -o "$file.part" "$BASE_URL/$name.bench"
  got="$(sha256sum "$file.part" | cut -c1-16)"
  if [ "$got" != "$sha" ]; then
    echo "checksum mismatch for $name.bench: $got != $sha" >&2
    rm -f "$file.part"
    exit 1
  fi
  mv "$file.part" "$file"
done <<'LIST'
c432 c3a37ac6850aa737
c499 a7a6a6c48c2b7c66
c880 6c8940cdbd4b59e3
c1355 21cf62a376a0fde9
c1908 948e4c168d412bb5
c2670 f9cea6f6734725b8
c3540 57c629ae6bbb9cd2
c5315 5da6e65f5df89a39
c7552 209d2aa40b31abec
LIST

# PySAT is installed into the container by environment/setup.sh.
